import React from 'react';

import PohButton, { ButtonSize } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import {
  addWorkoutTagUsageAsync,
  deleteWorkoutTagUsageAsync,
} from '../@services/workoutsTags.service';
import { IWorkoutTagUsage } from '../@types/workouts.types';
import { selectWorkoutTagAsync } from '../components/WorkoutTags/SelectWorkoutTagModal';
import WorkoutTag from '../components/WorkoutTags/WorkoutTag';

interface IWorkoutTagsProps {
  id_workout: number;
  tags: IWorkoutTagUsage[];
  onChangeTags: (tags: IWorkoutTagUsage[]) => void;
  canEdit?: boolean;
}

const WorkoutTags: React.FC<IWorkoutTagsProps> = ({ id_workout, tags, onChangeTags, canEdit }) => {
  return (
    <div className="d-flex align-items-center my-2">
      <small className="text-muted">Теги:</small>
      &nbsp;&nbsp;
      {tags.map((t) => {
        return (
          <WorkoutTag
            tag={t.tag}
            key={t.id}
            onDelete={
              canEdit
                ? async () => {
                    const ok = await confirmModal2('Удалить тег из тренировки?');
                    if (ok) {
                      await deleteWorkoutTagUsageAsync(t.id);
                      onChangeTags(tags.filter((x) => x.id !== t.id));
                    }
                  }
                : undefined
            }
          />
        );
      })}
      {canEdit && (
        <>
          &nbsp;&nbsp;&nbsp;
          <PohButton
            icon={IconsEnum.plus}
            onClick={async () => {
              const selectedTag = await selectWorkoutTagAsync(tags.map((x) => x.tag.id));
              const { id } = await addWorkoutTagUsageAsync({
                id_workout,
                id_workout_tag: selectedTag.id,
              });
              onChangeTags([...tags, { tag: selectedTag, id, createdAt: new Date() }]);
            }}
            size={ButtonSize.Small}
          />
        </>
      )}
    </div>
  );
};

export default WorkoutTags;
